import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture, mix, vec3 } from 'three/tsl';
import { Mesh, PlaneGeometry } from 'three/webgpu';

export default async function createNode(config, ctx) {
  const group = new ctx.THREE.Group();

  // Create plane geometry (512x320 pixels → ~1.6:1 aspect)
  // Atlas rect 0,0,512,320 suggests a card; scale to scene units
  const width = 1.6;
  const height = 1.0;
  const geometry = new PlaneGeometry(width, height);

  // Create material with brushed metal texture
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    side: ctx.THREE.FrontSide,
    transparent: false,
  });

  // Load brushed metal texture
  const metalTexture = await ctx.textureLoader.loadTexture(config.imageUrl);
  metalTexture.flipY = false;

  // Build shader: sample metal texture + add subtle grain overlay
  const uvNode = uv();
  const metalSample = texture(metalTexture, uvNode);

  // Grain: use time-independent noise pattern for static composition
  const grainUv = uvNode.mul(8.0);
  const grainPattern = mix(
    vec3(1.0),
    vec3(0.95),
    grainUv.fract().length().mul(0.05)
  );

  // Combine: metal texture × grain overlay for engineered surface
  const finalColor = metalSample.mul(grainPattern);

  material.colorNode = finalColor;

  // Create mesh and position in scene
  const mesh = new Mesh(geometry, material);
  mesh.position.copy(config.scenePosition ?? { x: 0, y: -0.3, z: 0 });

  if (config.rotation) {
    mesh.rotation.set(config.rotation.x ?? 0, config.rotation.y ?? 0, config.rotation.z ?? 0);
  }

  if (config.scale) {
    mesh.scale.set(config.scale.x ?? 1, config.scale.y ?? 1, config.scale.z ?? 1);
  }

  group.add(mesh);

  // Store metadata for atlas region (atlas 0, rect 0,0,512,320)
  group.userData.atlasRegion = {
    atlas: 0,
    rect: { x: 0, y: 0, w: 512, h: 320 },
  };

  // Cleanup: dispose geometry, material, and texture
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    metalTexture.dispose();
  };

  return group;
}
